import json
from pathlib import Path
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
for path in sorted(Path('world/pages').glob('reviews-*.json')):
    data = json.loads(path.read_text())
    def matches(value):
        if isinstance(value, dict):
            if value.get('subject') == 'site:shopify-catalogue-example' and value.get('digest') == digest:
                yield value
            for child in value.values():
                yield from matches(child)
        elif isinstance(value, list):
            for child in value:
                yield from matches(child)
    for review in matches(data):
        print(json.dumps({key: review.get(key) for key in ('seq', 'verdict', 'host_provider', 'host_turn')}, sort_keys=True))
